import React from 'react';
import '../styles/Servicios.css';

const OutsourcingContable = () => (
  <div className="servicios-container">
    <h2 className="servicios-title">Outsourcing Contable</h2>
    <p>Externaliza la gestión contable de tu empresa con nuestro equipo profesional, asegurando eficiencia, confidencialidad y cumplimiento legal.</p>
  </div>
);

export default OutsourcingContable;
